INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'dilmun-metalworks-2026-outlook', 'Dilmun Metalworks 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — دلمون للمعادن', 'Key operational benchmarks, real metrics, and 2026 guidance from Dilmun Metalworks in Askar.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من دلمون للمعادن في Askar.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ISO-9001 certified industrial fabrication plant producing custom CNC machined components, architectural aluminium louvers, and steel frames. Focusing on 5-Axis CNC Custom Machining Batch, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مصنع معتمد وفق آيزو 9001 لإنتاج القطع المعدنية الدقيقة وهياكل الصلب والألمنيوم المعماري. من خلال خدمة تشغيل آلي خماسي المحاور CNC نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>ISO-9001 certified industrial fabrication plant producing custom CNC machined components, architectural aluminium louvers, and steel frames.</p><p>Focusing on <strong>5-Axis CNC Custom Machining Batch</strong>, our Askar specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مصنع معتمد وفق آيزو 9001 لإنتاج القطع المعدنية الدقيقة وهياكل الصلب والألمنيوم المعماري.</p><p>من خلال خدمة <strong>تشغيل آلي خماسي المحاور CNC</strong>، يعمل فريقنا في Askar على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'Dilmun Metalworks 2026 GCC Market Outlook & Benchmarks | Dilmun Metalworks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — دلمون للمعادن | دلمون للمعادن', 'Executive guide by Dilmun Metalworks covering 5-Axis CNC Custom Machining Batch benchmarks in Bahrain.', 'دليل تنفيذي من دلمون للمعادن حول معايير تشغيل آلي خماسي المحاور CNC في البحرين.', 'Insights', '{"manufacturing","insights","Askar","2026"}'::text[], 'Hana Yousef', 'draft', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can Dilmun Metalworks initiate a 5-Axis CNC Custom Machining Batch engagement?', 'كم يستغرق بدء تنفيذ خدمة تشغيل آلي خماسي المحاور CNC لدى دلمون للمعادن؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Askar.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Askar.', 'services', false, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
