ral Powder Coating benchmarks in Bahrain.', 'دليل تنفيذي من دلمون للمعادن حول معايير طلاء بودرة حراري معماري في البحرين.', 'Client Care', '{"manufacturing","client care","Askar","2026"}'::text[], 'Bader Ali', 'draft', now() - interval '72 days', false, now() - interval '72 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-12', 'What post-delivery guarantee covers your work?', 'ما الضمان المقدم بعد التسليم النهائي؟', 'All engagements include a structured handover checklist and 30-to-90 day defect/warranty support window.', 'تشمل جميع المشاريع قائمة استلام موثقة وفترة ضمان ودعم تمتد بين 30 و90 يوماً بعد التسليم.', 'warranty', false, 12, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
